// Why is the sky blue: it isn't always #WCCChallenge from @sableRaph Birb´s Nest Discord
// https://discord.com/channels/820953351817789480/896810496618020905
//
// Hello Raph and fellow creative coders,
// I think, that we all learned now, why the sky is blue.
// But it isn't always blue, so there is an implementation 
// of the change of color in the sky (not a physically correct).
//
// Video on https://www.twitch.tv/videos/1853569115

var t, br, minWH, sunSize, sun;

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1);
	minWH = max(width, height);
	sunSize = minWH * 0.3;
	colorMode(HSB, 360, 100, 100, 1);
}

function windowResized() {
	setup();
}

function draw() {
	t = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0, 1); // 0 .. 1 depending on (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) position
	br = pow(1 - abs(t - 0.5), 1.2); // ~0 .. 1 .. ~0

	drawBackground();
	drawStars(200);
	drawSky(200);
	drawSun();	
	drawSky(50, 0.15);
	drawEarth();
}

function drawBackground() {
	push();
	// backgroundbackground(225 + (1 - br) * 135, 50, 10 + 50 * br);
	// background var 0= blue, 0.1 red, 0.2 = blue
	let st = 0; 
	if (t > 0.1 && t < 0.25) 
		st = (cos(map(t, 0.1, 0.25, PI, 3 * PI)) + 1) / 2;
	if (t > 0.75 && t < 0.9) 
		st = (cos(map(t, 0.75, 0.9, PI, 3 * PI)) + 1) / 2;

	let clrBgTop = color(225 + st * 135, 20 + 50 * br, 0 + 50 * br)
	let clrBgBottom = color(225, 20 + 50 * br, 0 + 50 * br)
	background(clrBgTop);

	const gradient = drawingContext.createLinearGradient(0, 0, 0, height);
	gradient.addColorStop(0, clrBgTop);
	gradient.addColorStop(1, clrBgBottom);
	drawingContext.fillStyle = gradient;
	rect(0, 0, width, height);

	pop();
}

function drawSun() {
	// draw the sun
	// color sun: br 0 = blue, 0.1 purple, 0.2 - 0.5 blue
	let x = bezierPoint(width * 0, width * 0.33, width * 0.67, width, t);
  let y = bezierPoint(height, height * 0.1, height * 0.1, height, t);
	push()
	noStroke()
	fill("white")
	drawingContext.shadowBlur = minWH * 0.1;
  drawingContext.shadowColor = "white";
	circle(x, y, sunSize);
	let sunClr = color(60 - 1.5 * (1 - br) * 60, 100 - 24 * br, 50 + 50 * br);
	fill(sunClr)
	drawingContext.shadowBlur = minWH * 0.25;
  drawingContext.shadowColor = sunClr;
	circle(x, y, sunSize);
	pop();

	sun = {x, y, c: sunClr};
}

function drawSky(num, a = 1) {
	// draw the sky
	push();
	noStroke();
	for (let i = 0; i < num; i++) {
		var x = map(noise(frameCount * 0.001 + i * 0.1), 0, 1, -0.3, 1.3) * width; // map(noise(frameCount * 0.001 + i * 0.1), 0, 1, -0.3, 1.3) * width;
		var y = noise(frameCount * 0.002 + i * 0.21) * height * 0.9 - height * 0.2;
		const d = noise(frameCount * 0.00432 + i * 0.0514) * minWH * 0.25 + minWH * 0.05
		const c = noise(frameCount * 0.0032 + i * 0.14) * 100 - 50
		fill(c + 225 + (1 - br) * 135, 50, 10 + 50 * br, a * 0.15);
		circle(x, y, d);
	}
	pop();
}

function drawStars(num = 1000) {
	// draw the stars
	const a = (1 - br);
	push();
	for (let i = 0; i < num; i++) {
		var x = map(noise(-(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) * 0.000021 + i * 0.21), 0, 1, -0.3, 1.3) * width;
		var y = noise(-(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) * 0.000012 + i * 0.121) * height * 0.7 - height * 0.15;
		const s = noise(frameCount * 0.00432 + i * 0.0514) * 4 + 1;
		var d = noise(frameCount * 0.0032 + i * 0.14) * 0.5 + 0.5; // alpha 0..1
		strokeWeight(s);
		stroke(0, 0, 100, a * d);
		point(x, y);
	}
	pop();
}


function drawEarth() {
	// draw earth
	push();
	noStroke();

	// fill(30, 60 + 40 * br, 25 + 25 * br, 1)
	const clrEarthTop = sun.c;
	const clrEarthBottom = color(30, 60 + 40 * br, 25 + 25 * br, 1);
	var gradient = drawingContext.createLinearGradient(sun.x, sun.y, width * 0.5, height);
	gradient.addColorStop(0, clrEarthTop);
	gradient.addColorStop(1, clrEarthBottom);
	drawingContext.fillStyle = gradient;

	beginShape();
  vertex(0, height);
  vertex(0, height * 0.9);
  bezierVertex(width * 0.33, height * 0.80, width * 0.67, height * 0.80, width, height * 0.9);
  // bezierVertex(width * 0.25, height * 0.8, width * 0.25, height * 0.8, width * 0.5, height * 0.8);
  // bezierVertex(width * 0.75, height * 0.8, width * 0.75, height * 0.8, width, height * 0.9);
  vertex(width, height);
  endShape(CLOSE);
	pop();
}
